let toastTimer;
// An optional action (such as Undo) makes the toast clickable and keeps it up a little longer.
function toast(t,action){const el=$('#toast');clearTimeout(toastTimer);el.innerHTML=esc(t)+(action?`<button type="button" class="toast-action">${esc(action.label)}</button>`:'');el.classList.toggle('has-action',!!action);if(action)el.querySelector('.toast-action').onclick=()=>{clearTimeout(toastTimer);el.classList.remove('visible');action.run()};el.classList.add('visible');toastTimer=setTimeout(()=>el.classList.remove('visible'),action?7000:3000)}
function err(e){toast(e.message||'Something went wrong. Please try again.')}
function seriesChart(rows,stroke='#8ca883',average=null){
 if(rows.length<2)return '<div class="chart-empty">'+(rows.length?'One recorded measurement':'No measurements in this period')+'</div>';
 const values=rows.map(r=>Number(r.value)),min=Math.min(...values),max=Math.max(...values),span=max-min||1;
 const start=Date.parse(rows[0].observed_at),duration=Date.parse(rows.at(-1).observed_at)-start||1;
 const points=rows.map(r=>`${((Date.parse(r.observed_at)-start)/duration*236+2).toFixed(2)},${(48-(Number(r.value)-min)/span*38).toFixed(2)}`).join(' ');
 return `<svg class="spark" viewBox="0 0 240 55" preserveAspectRatio="none" role="img" aria-label="${rows.length} recorded measurements">${average!==null?`<line class="average-guide" x1="0" x2="240" y1="${48-(average-min)/span*38}" y2="${48-(average-min)/span*38}" stroke="${stroke}" stroke-opacity=".5" stroke-dasharray="4 4"/>`:""}<polyline points="${points}" stroke="${stroke}" fill="none" stroke-width="1.5"/></svg>`;
}
function reading(k){return readings.find(r=>r.kind===k)}
// A wearable reading older than a few days is shown as "last recorded", never as today's value.
const isStale=m=>m.group!=='body'&&!!staleDays(reading(m.kind));
const freshFirst=list=>[...list].sort((a,b)=>Number(isStale(a))-Number(isStale(b)));
function cards(list=metrics,compact=false,heroKind=null){return list.map(m=>{const r=reading(m.kind),own=readings.filter(x=>x.kind===m.kind&&x.source===r?.source&&x.unit===r?.unit),series=metricSeries(own,m.kind,30),average=metricSummary(series),date=r?new Date(r.observed_at).toLocaleDateString(dateLocale,{month:'short',day:'numeric'}):'',stale=m.group!=='body'?staleDays(r):0,compare=r&&!stale?compareLatest(own,r):null;const delta=r&&!stale&&average.days>=3?metricDelta(r.value,average.mean):null,unusual=!!(delta&&compare?.unusual);
 const pill=stale?`<span class="vpill stale" title="Last reading ${stale} days ago">Last ${date}</span>`:delta?`<span class="vpill ${unusual?'unusual':''}" title="${unusual?'Unusual for you: outside your usual 30-day range. ':''}${delta.title}">${unusual?'Unusual · ':''}${delta.label}${delta.direction==='flat'?'':'<span class="vs">&nbsp;vs 30d</span>'}</span>`:'';
 const foot=r?[esc(r.source),average.mean!==null?`30d avg <strong>${formatValue(average.mean,m.kind)}</strong>`:`Last recorded ${date}`]:[m.group==='body'?'Add your measurement':'Connect a source',''];
 return vcard({m,r,rows:own,pill,foot,hero:m.kind===heroKind,stale:!!stale,readings,empty:m.group==='body'?'Add a measurement to get started':'No reading yet'})}).join('')}

function vitalsPage(){const available=freshFirst(metrics.filter(m=>m.group!=='sleep'&&m.group!=='body'&&reading(m.kind)));return `${available.length?'':dataCallout()}<div class="page-bento">${cards(available.length?available:metrics.slice(0,6).filter(m=>m.kind!=='sleep'))}</div>`}
function sleepPage(){const latest=reading('sleep'),lastNight=latest&&!staleDays(latest)?latest:null,stages=lastNight?[['sleep_deep','Deep','#8e9db5'],['sleep_rem','REM','#b2a2bf'],['sleep_light','Light','#c9cfdf']].map(([kind,name,color])=>({kind,name,color,row:readings.find(r=>r.kind===kind&&r.source===latest?.source&&r.observed_at.slice(0,10)===latest?.observed_at.slice(0,10))})).filter(s=>s.row):[];
 // Stage figures are rounded so they add up to the hours shown, instead of 8.4 h of stages in an 8.3 h night.
 const shown=apportion(stages.map(s=>Number(s.row.value)),Number(latest?.value||0));stages.forEach((s,i)=>s.shown=shown[i]);const list=freshFirst(metrics.filter(m=>m.group==='sleep'&&reading(m.kind)));return `${latest?'':dataCallout()}${latest&&!lastNight?`<section class="panel sleep-overview is-stale"><div><div class="eyebrow">Last recorded night</div><h2>${new Date(latest.observed_at).toLocaleDateString(dateLocale,{weekday:'long',month:'long',day:'numeric'})}</h2><p>${esc(latest.source)} has not recorded a night in the last ${staleDays(latest)} days. Older readings are shown below with their date.</p></div></section>`:''}${stages.length?`<section class="panel sleep-overview"><div><div class="eyebrow">Last recorded night</div><h2>${formatValue(latest.value,'sleep')}<small> hours asleep</small></h2><p>${esc(latest.source)} · Sleep stages</p></div><div class="sleep-stages"><div class="stage-bar">${stages.map(s=>`<i style="flex:${s.row.value};background:${s.color}" title="${s.name}: ${s.shown.toLocaleString(dateLocale,{maximumFractionDigits:1})} hours"></i>`).join('')}</div><div class="stage-legend">${stages.map(s=>`<span><i style="background:${s.color}"></i>${s.name}<strong>${s.shown.toLocaleString(dateLocale,{maximumFractionDigits:1})} h</strong></span>`).join('')}</div></div></section>`:''}${latest?goalsPanel():''}<div class="page-bento">${cards(list.length?list:metrics.filter(m=>['sleep','sleep_performance','sleep_efficiency'].includes(m.kind)))}</div>`}
// Goals are the person's own; debt adds up shortfalls only, so a long night does not cancel a short one.
const preferences=()=>({sleep_goal:8,recovery_goal:66,...(data.user?.user_metadata?.preferences||{})});
function goalsPanel(){const {sleep_goal:goal,recovery_goal:rgoal}=preferences(),night=reading('sleep'),own=readings.filter(r=>r.kind==='sleep'&&r.source===night?.source),now=Date.now(),sum=sleepGoalSummary(own,goal,{now}),before=sleepGoalSummary(own,goal,{now:now-7*86400000}),rec=reading('recovery'),recDays=dailyMeans(readings.filter(r=>r.kind==='recovery'&&r.source===rec?.source),{days:14}),hours=v=>v.toLocaleString(dateLocale,{maximumFractionDigits:1}),change=sum.debt-before.debt,scale=goal*1.4;
 return `<section class="panel goals-panel"><div class="panel-head"><div><span class="eyebrow">Your goals</span><h3>Sleep and recovery</h3></div><button class="text-button" data-action="edit-goals">Change goals</button></div><div class="goal-grid"><div class="goal-block"><span>Sleep goal</span><strong>${hours(goal)}<small> h</small></strong><p>${sum.days.length?`Met on ${sum.met} of ${sum.days.length} recorded nights in the last 14 days.`:'No recorded nights in the last 14 days.'}</p></div><div class="goal-block"><span>Sleep debt · last 7 nights</span><strong>${hours(sum.debt)}<small> h</small></strong><p>${before.days.length?`${Math.abs(change)<.05?'Same as':`${hours(Math.abs(change))} h ${change>0?'more than':'less than'}`} the 7 nights before.`:'Hours below your goal, added up.'}</p></div><div class="goal-block"><span>Recovery goal</span><strong>${rgoal}<small> %</small></strong><p>${recDays.length?`Reached on ${recDays.filter(d=>d.value>=rgoal).length} of ${recDays.length} days in the last 14.`:'No recovery readings in the last 14 days.'}</p></div></div>${sum.days.length?`<div class="goal-bars" role="img" aria-label="Sleep on the last ${sum.days.length} recorded nights against your ${hours(goal)} hour goal">${sum.days.map(d=>`<i class="${d.value>=goal?'met':''}" style="--h:${Math.min(100,d.value/scale*100).toFixed(1)}%" title="${new Date(d.day+'T12:00:00Z').toLocaleDateString(dateLocale,{month:'short',day:'numeric'})}: ${hours(d.value)} h"></i>`).join('')}<span class="goal-line" style="--g:${(goal/scale*100).toFixed(1)}%"><b>${hours(goal)} h goal</b></span></div>`:''}</section>`}
function editGoals(){const {sleep_goal,recovery_goal}=preferences();showModal(`${heading('Your goals','Sleep')}<p>Set targets that suit you. Xeyo compares your recorded nights and recovery with them.</p><form id="goals-form"><div class="form-grid"><label class="field">Sleep goal (hours)<input name="sleep_goal" type="number" min="4" max="12" step="0.25" required value="${sleep_goal}"></label><label class="field">Recovery goal (%)<input name="recovery_goal" type="number" min="1" max="100" step="1" required value="${recovery_goal}"></label></div><div id="form-error"></div><div class="dialog-footer"><span>Saved to your account.</span><button class="btn" type="submit">Save goals</button></div></form>`);$('#goals-form').onsubmit=e=>{e.preventDefault();busy(e.target,async()=>{const v=new FormData(e.target);await data.savePreferences({sleep_goal:Number(v.get('sleep_goal')),recovery_goal:Number(v.get('recovery_goal'))});closeModal();await render();toast('Goals saved')})}}
function currentBoard(){return boardDraft||normalizeLayout(data.user?.user_metadata?.dashboard_layout,data.user?.user_metadata?.dashboard)}
async function editDashboard(){if(boardDraft)return;boardDraft=structuredClone(currentBoard());page='Home';await render();document.querySelector('#board-add')?.focus();}
async function redrawBoard(focus){await render();if(focus)document.querySelector(focus)?.focus();}
function editTools(){return boardDraft?`<section class="board-toolbar" aria-label="Dashboard editing"><div><span class="eyebrow">Make it yours</span><h2>Widgets</h2><p>Drag a handle to rearrange. Choose a size, or add something new.</p></div><div class="actions"><button id="board-add" class="btn light" data-action="add-widgets">${icon('plus')} Add widgets</button><button class="text-button" data-action="cancel-board">Cancel</button><button class="btn" data-action="save-board" ${boardSaving?'disabled':''}>${boardSaving?'Saving…':'Done'}</button></div></section>`:'';}
function bindBoard(){if(!boardDraft)return;bindWidgetEditing($('#page'),{remove:id=>{boardDraft.widgets=boardDraft.widgets.filter(w=>w.id!==id);redrawBoard('#board-add')},resize:(id,size)=>{boardDraft.widgets.find(w=>w.id===id).size=size;redrawBoard(`[data-size-widget="${id}"][data-size="${size}"]`)},move:(id,delta,target)=>{const index=target?boardDraft.widgets.findIndex(w=>w.id===target):boardDraft.widgets.findIndex(w=>w.id===id)+delta;boardDraft.widgets=moveWidget(boardDraft.widgets,id,index);redrawBoard(`[data-drag-widget="${id}"]`)}});}
function widgetGallery(){let group='all',search='';showModal(`${heading('A little more you.','Widget gallery')}<p>Choose what matters. Every widget uses your own recorded data.</p><label class="widget-search"><input id="widget-search" type="search" placeholder="Search widgets" aria-label="Search widgets"></label><div class="widget-categories">${[['all','All'],['vitals','Vitals'],['sleep','Sleep'],['body','Body'],['activity','Activity'],['daily','Daily life']].map(([id,n])=>`<button data-widget-group="${id}" aria-pressed="${id===group}">${n}</button>`).join('')}</div><div id="widget-gallery" class="widget-gallery"></div><p id="widget-count" class="mini-note" role="status"></p>`,true);
 // Widgets with data come first; ones nothing has recorded yet are flagged rather than looking ready.
 const hasData=m=>m.group==='daily'||!!reading(m.kind);
 const draw=()=>{const list=widgetCatalog.filter(m=>(group==='all'||m.group===group)&&m.name.toLowerCase().includes(search.toLowerCase())).sort((a,b)=>Number(hasData(b))-Number(hasData(a)));$('#widget-gallery').innerHTML=list.map(m=>{const added=boardDraft.widgets.some(w=>w.id===m.kind),r=reading(m.kind);return `<button class="widget-choice ${m.color} ${m.stroke?'has-accent':''} ${hasData(m)?'':'no-data'}" ${m.stroke?`style="--accent:${m.stroke}"`:''} data-add-widget="${m.kind}" ${added?'disabled':''}><div class="widget-choice-head">${m.stroke?metricIcon(m.kind):''}<span>${m.name}</span><b>${added?'✓':'+'}</b></div><div class="widget-preview-number">${r?formatValue(r.value,m.kind):m.kind==='nutrition'?Math.round(totals(mealData).calories):m.kind==='digestive'?'↗':'—'}<small>${m.kind==='nutrition'?'kcal':m.unit}</small></div><small>${added?'On your dashboard':r?esc(r.source):m.group==='daily'?'Your daily view':'<b class="no-data-flag">No data yet</b> Shows once a source records it'}</small></button>`}).join('')||'<p>No matching widgets.</p>';$('#widget-count').textContent=`${boardDraft.widgets.length} on your dashboard · room for ${16-boardDraft.widgets.length} more · ${widgetCatalog.filter(hasData).length} of ${widgetCatalog.length} have data`;document.querySelectorAll('[data-add-widget]').forEach(b=>b.onclick=async()=>{if(boardDraft.widgets.length>=16){toast('Your dashboard holds up to 16 widgets.');return}boardDraft.widgets.push({id:b.dataset.addWidget,size:['nutrition','digestive'].includes(b.dataset.addWidget)?'medium':'small'});await render();draw();});};
 $('#widget-search').oninput=e=>{search=e.target.value;draw()};document.querySelectorAll('[data-widget-group]').forEach(b=>b.onclick=()=>{group=b.dataset.widgetGroup;document.querySelectorAll('[data-widget-group]').forEach(el=>el.setAttribute('aria-pressed',String(el===b)));draw()});draw();}
function syncControl(){const last=connections.find(c=>c.provider==='whoop')?.last_synced_at;const detail=syncState.error?'Could not refresh. Select to retry.':syncState.inProgress?'Sync running in another tab':last?'Last WHOOP sync: '+new Date(last).toLocaleString(dateLocale,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}):syncState.checkedAt?'Records updated '+new Date(syncState.checkedAt).toLocaleTimeString(dateLocale,{hour:'numeric',minute:'2-digit'}):'Refresh your records';return `<button class="btn light refresh-data ${syncState.busy?'is-syncing':''} ${syncState.error?'sync-retry':''}" data-action="refresh" aria-label="${syncState.error?'Retry refreshing data':'Refresh data'}" aria-describedby="sync-description" ${syncState.busy?'disabled':''} title="${esc(detail)}">${icon('refresh')}<span>${syncState.busy?'Refreshing':syncState.error?'Retry':'Refresh'}</span></button><span id="sync-description" class="sr-only" role="status">${syncState.busy?'Updating your connected data…':esc(detail)}</span>`;}
function updateSyncControl(){const host=$('#sync-control');if(host){host.innerHTML=syncControl();wire(host);}}
const syncController=createSyncController({loadConnections:async()=>{const s=await data.api('connections');return s.connections||[]},sync:()=>data.api('whoop-sync'),reload:async()=>{await refresh();if(data.user&&!boardDraft&&!$('#onboard-form')&&!chatOpen&&!['Nutrition','Journal'].includes(page))await render()},onState:state=>{if(!data.user)return;syncState={...syncState,...state};updateSyncControl();}});
async function refreshConnected(manual=false){const result=await syncController.run();if(manual)toast(result.ok?result.inProgress?'WHOOP sync is already running. Refresh again shortly.':result.live?'Connected readings refreshed':'Saved records refreshed. Manage sources to connect a wearable.':syncState.error||'Could not refresh. Your saved readings are still available.');}

// Callouts connect the body to its cards: on Home they carry the status, not a second copy of the number.
function signalStatus(kind){const r=reading(kind);if(!r)return ['No reading',''];const stale=staleDays(r);if(stale)return ['Last '+new Date(r.observed_at).toLocaleDateString(dateLocale,{month:'short',day:'numeric'}),''];const own=readings.filter(x=>x.kind===kind&&x.source===r.source),avg=metricSummary(metricSeries(own,kind,30)),d=avg.days>=3?metricDelta(r.value,avg.mean):null,c=compareLatest(own,r);return d?[(c?.unusual?'Unusual · ':'')+d.label,c?.unusual?'unusual':'']:['Recorded','']}
function bodySignals(exclude=[]){return [['resting_hr','Resting heart rate','bpm','heart'],['spo2','Blood oxygen','%','oxygen'],['respiratory_rate','Respiratory rate','/min','breathing']].map(([kind,label,unit,position])=>{const r=reading(kind),onBoard=exclude.includes(kind),[status,tone]=signalStatus(kind),copy=`<span class="signal-copy">${label}${onBoard?`<em class="signal-pill ${tone}">${esc(status)}</em>`:`<strong>${r?formatValue(r.value,kind):'—'} <small>${unit}</small></strong>`}</span>`,point='<span class="signal-line"></span><span class="signal-dot"></span>';return exclude.length?`<button class="body-signal connector signal-${position}" data-metric="${kind}" aria-label="Explore ${metrics.find(m=>m.kind===kind).name.toLowerCase()}"><span class="signal-dot"></span><span class="signal-line"></span>${copy}</button>`:`<button class="body-signal signal-${position}" data-metric="${kind}" aria-label="Explore ${metrics.find(m=>m.kind===kind).name.toLowerCase()}">${position!=='breathing'?copy+point:'<span class="signal-dot"></span><span class="signal-line"></span>'+copy}</button>`}).join('')}
function portrait(signals=false,exclude=[]){const image='<img class="human-portrait" src="/images/human-portrait.png" alt="Illustrative portrait of a curly-haired adult in soft natural light" width="1024" height="1536" fetchpriority="high">';return `<div class="portrait-scene ${signals?'portrait-anchored':''}"><div class="portrait-halo"></div>${signals?`<div class="portrait-figure">${image}${bodySignals(exclude)}</div>`:image}</div>`}
// Pointer-driven depth for the avatar; skipped for reduced motion and touch-only devices.
function bindDepth(root=app){if(matchMedia('(prefers-reduced-motion: reduce)').matches||!matchMedia('(hover: hover)').matches)return;root.querySelectorAll('.portrait-scene').forEach(scene=>{const figure=scene.querySelector('.human-portrait,.vitruvian-image');if(!figure)return;let frame=0;scene.onpointermove=e=>{cancelAnimationFrame(frame);frame=requestAnimationFrame(()=>{const r=scene.getBoundingClientRect(),x=(e.clientX-r.left)/r.width-.5,y=(e.clientY-r.top)/r.height-.5;scene.classList.add('is-tilting');figure.style.setProperty('--tilt-y',(x*14).toFixed(2)+'deg');figure.style.setProperty('--tilt-x',(-y*8).toFixed(2)+'deg')})};scene.onpointerleave=()=>{cancelAnimationFrame(frame);scene.classList.remove('is-tilting');figure.style.removeProperty('--tilt-y');figure.style.removeProperty('--tilt-x')}})}
function hasRepresentation(){return profile?.representation==='digital'||profile?.representation==='photo'}
function vitruvianVisual(exclude=[]){const figure=digitalFigure(profile?.gender);return `<div class="portrait-scene portrait-anchored vitruvian-scene"><div class="portrait-halo"></div><div class="portrait-figure vitruvian-figure"><img class="vitruvian-image" src="${figure.src}" alt="${figure.alt}" width="1024" height="1024">${bodySignals(exclude)}</div></div>`}
function personalVisual(exclude=[]){if(profile?.representation==='digital')return vitruvianVisual(exclude);if(portraitURL)return `<div class="portrait-scene portrait-anchored personal-portrait"><div class="portrait-halo"></div><div class="portrait-figure"><img class="human-portrait" src="${esc(portraitURL)}" alt="Your personal AI portrait in the Xeyo style">${bodySignals(exclude)}</div></div>`;return portrait(true,exclude);}
function portraitStudio(){if(!profile?.photo_record_id||profile.representation!=='photo'){choosePortraitPhoto();return;}openPortraitStudio({sourceId:profile.photo_record_id,api:data.api,showModal,heading,closeModal,connect:()=>aiSettings(()=>portraitStudio()),changePhoto:choosePortraitPhoto,accepted:async()=>{await refresh();await render();toast('Your portrait is ready')}});}
function choosePortraitPhoto(){
 if(!profile){profileSetup();return;}
 showModal(`${heading('Start with a photo of you.','Your personal portrait')}<p>Choose a clear photo of yourself with your face and shoulders visible. We use it for your likeness and the original human for the portrait’s lighting and composition.</p><form id="portrait-photo-form"><label class="upload-zone" style="margin-top:24px">${icon('camera')}<span>Choose your photo</span><input type="file" name="photo" accept="image/*,.heic,.heif" required></label><p class="mini-note">JPG, PNG, WebP or HEIC · Resized on your device and stripped of location data · Stored privately. The photo is sent to OpenAI only when you choose Generate.</p><div id="form-error"></div><div class="dialog-footer"><span class="mini-note">Your likeness. Soft light. Bare shoulders.</span><button type="submit" class="btn">Continue to portrait studio ↗</button></div></form>`);
 $('#portrait-photo-form').onsubmit=e=>{e.preventDefault();busy(e.target,async()=>{await data.saveProfile({...profile,representation:'photo'},e.target.elements.photo.files[0]);await refresh();closeModal();await render();portraitStudio();})};
}
function profileSetup(){
 mealLogger.cancel();const previous=profile?.photo_record_id;
 openOnboarding({app,profile,photos:records.filter(r=>r.kind==='photo'),orb,save:data.saveProfile,done:async saved=>{
  const photoChanged=saved?.representation==='photo'&&saved.photo_record_id&&saved.photo_record_id!==previous;
  if(saved){profile=saved;if(saved.photo_record_id!==previous)portraitURL=null;portraitChecked=Date.now();}
  page='Home';await render();window.scrollTo(0,0);
  // Setup is complete once the profile is confirmed. Background data failures belong
  // to the dashboard's refresh control, not to the onboarding save button.
  if(saved)void refreshConnected();
  if(photoChanged)portraitStudio();
 },signOut:actions.logout});
}

async function loadPeers(){try{peerResult=await data.peerPercentiles()}catch(e){peerResult={status:'error',message:e.message}}const host=$('#profile-peers');if(page==='Profile'&&host){host.innerHTML=peerPage(peerResult);wire(host);}}
function dashboardWidget(id,hero){if(id==='nutrition')return nutritionWidget();if(id==='digestive')return journalWidget(journalData,journalError);if(id==='measurements')return measureCard();return cards([metrics.find(m=>m.kind===id)],true,hero?id:null);}
// How much the person's sources recorded in the last 30 days.
function measureCard(){const since=Date.now()-30*86400000,recent=readings.filter(r=>Date.parse(r.observed_at)>=since),sources=new Set(recent.map(r=>r.source)).size;return `<section class="vcard vpanel pal-lagoon measure-card"><span class="vcard-head"><h3>Measurements</h3><button class="vcard-arrow" data-nav="Vitals" aria-label="Open vitals">↗</button></span><span class="vcard-value"><b>${recent.length.toLocaleString(dateLocale)}</b><small>readings</small></span><span class="vcard-visual">${wireOrb('orb-measure')}</span><span class="vcard-foot"><span>Last 30 days</span><span>${sources} ${sources===1?'source':'sources'}</span></span></section>`}
// Statistics view: the signal's last two weeks on a dark field, days above the person's own average in the accent.
function trendCard(kind){const m=metrics.find(x=>x.kind===kind),r=reading(kind);if(!m||!r)return '';const days=dailyMeans(readings.filter(x=>x.kind===kind&&x.source===r.source&&x.unit===r.unit),{days:14});if(days.length<2)return '';const mean=days.reduce((s,d)=>s+d.value,0)/days.length,values=days.map(d=>d.value),min=Math.min(...values,mean),max=Math.max(...values,mean),y=v=>(88-(v-min)/(max-min||1)*72).toFixed(1),x=i=>(i/(days.length-1)*100).toFixed(1),pts=days.map((d,i)=>`${x(i)} ${y(d.value)}`),above=days.filter(d=>d.value>mean).length;
 return `<section class="vcard vpanel pal-noir trend-card"><span class="vcard-head"><h3>${esc(m.name)} · last ${days.length} days</h3><button class="vcard-arrow" data-metric="${kind}" aria-label="Open ${esc(m.name)}">↗</button></span><span class="vcard-value"><b>${formatValue(r.value,kind)}</b><small>${esc(m.unit)}</small></span><span class="vcard-pills"><span class="vpill">Above your average on ${above} of ${days.length} days</span></span><span class="vcard-visual"><svg class="vline" viewBox="0 0 100 100" preserveAspectRatio="none" role="img" aria-label="${esc(m.name)} over the last ${days.length} days, with days above your average highlighted"><defs><clipPath id="trend-above"><rect x="0" y="0" width="100" height="${y(mean)}"/></clipPath></defs><path d="M${pts.join(' L')} L100 ${y(mean)} L0 ${y(mean)} Z" class="above" clip-path="url(#trend-above)"/><line x1="0" x2="100" y1="${y(mean)}" y2="${y(mean)}" class="mean"/><path d="M${pts.join(' L')}" class="trace"/></svg></span><span class="trend-days">${days.filter((_,i)=>i%2===0||i===days.length-1).map(d=>`<span>${new Date(d.day+'T12:00:00Z').toLocaleDateString(dateLocale,{weekday:'short'})}</span>`).join('')}</span><span class="vcard-foot"><span>${esc(r.source)}</span><span>Dashed line: your 14-day average</span></span></section>`}
function figureCard(){const image=portraitURL||(profile?.representation==='digital'?digitalFigure(profile?.gender).src:'/images/human-portrait.png'),now=new Date();return `<section class="vcard vpanel figure-card"><img src="${esc(image)}" alt=""><span class="figure-title">${now.toLocaleDateString(dateLocale,{month:'long'})} <span>${now.getFullYear()}</span></span><div class="figure-links"><button data-nav="Sleep">Sleep goals</button><button data-nav="Journal">Check-ins</button><button data-nav="Blood records">Blood results</button></div></section>`}
function todayEvents(){const today=localDay(),events=[],night=reading('sleep');if(night&&localDay(new Date(night.observed_at))===today)events.push({kind:'wake',at:new Date(night.observed_at),label:'Woke up · '+formatValue(night.value,'sleep')+' h asleep',nav:'Sleep'});for(const m of mealData)if(m.created_at&&localDay(new Date(m.created_at))===today)events.push({kind:'meal',at:new Date(m.created_at),label:m.name,nav:'Nutrition'});for(const e of journalData)if(e.logged_on===today&&e.created_at)events.push({kind:'journal',at:new Date(e.created_at),label:'Journal check-in',nav:'Journal'});return events.sort((a,b)=>a.at-b.at)}
// Today's nutrition on a dark field: energy, macro share of that energy, and the latest meal.
function nutritionWidget(){const t=totals(mealData),energy=t.protein*4+t.carbs*4+t.fat*9,share=k=>energy?Math.round(t[k]*(k==='fat'?9:4)/energy*100):0,last=mealData[0],row=(k,name)=>`<div class="${k}"><span>${name}</span><i style="width:${Math.max(energy?4:0,share(k))}%"></i><b>${Math.round(t[k])} g · ${share(k)}%</b></div>`;return `<section class="vcard vpanel pal-noir nutrition-card"><span class="vcard-head"><h3>Today’s nutrition</h3><button class="vcard-arrow" data-nav="Nutrition" aria-label="Open nutrition">↗</button></span><span class="vcard-value"><b>${Math.round(t.calories).toLocaleString(dateLocale)}</b><small>kcal</small><span class="vcard-pills inline"><span class="vpill">${mealData.length} ${mealData.length===1?'meal':'meals'} logged</span></span></span><div class="macro-dots" role="img" aria-label="${energy?`Protein ${share('protein')}%, carbs ${share('carbs')}%, fat ${share('fat')}% of logged energy`:'No macros logged yet'}">${row('protein','Protein')}${row('carbs','Carbs')}${row('fat','Fat')}</div><span class="vcard-foot" style="margin-top:auto"><span>${last?'Latest: '+esc(last.name):'Nothing logged yet'}</span><span>Estimated from your meals</span></span></section>`}
// Up to three notable changes against the person's own 30-day average, most unusual first.
function homeInsights(limit=3){const list=metricInsights(readings,metrics,{limit}),fresh=readings.some(r=>!staleDays(r));if(!list.length&&!fresh)return '';return `<div class="home-insights"><span class="eyebrow">Compared with you</span>${list.length?list.map(i=>`<button class="insight ${i.unusual?'unusual':''}" data-metric="${i.kind}"><span>${esc(insightText(i))}</span>${i.unusual?'<b>Unusual for you</b>':''}</button>`).join(''):'<p>Your signals are close to your usual 30-day range.</p>'}<button class="text-button" data-action="weekly">Your week, in summary ↗</button></div>`}
function dataCallout(){return readings.length?'':`<section class="panel data-callout"><div><h3>No measurements yet</h3><p>Connect WHOOP, or import Apple Health or Fitbit data. You can also look around with sample data first.</p></div><div class="actions"><button class="btn" data-nav="Integrations">Connect a source</button><button class="btn light" data-action="demo-on">Explore with sample data</button></div></section>`}
// The hero card is the one the person sized large, otherwise their recovery or HRV.
function heroKind(layout){return layout.widgets.find(w=>w.size==='large'&&metrics.some(m=>m.kind===w.id))?.id||['recovery','hrv','sleep_performance','sleep'].find(k=>layout.widgets.some(w=>w.id===k)&&reading(k))||null}
function home(){const layout=currentBoard(),onBoard=layout.widgets.map(w=>w.id),insights=homeInsights(hasRepresentation()?2:3),hero=heroKind(layout),trend=hasRepresentation()||boardDraft?'':trendCard(hero||layout.widgets.find(w=>reading(w.id))?.id),tile=trend?null:hero,packed=packBento(layout.widgets,{hero:tile,cols:trend?4:3,startRow:trend?3:1});return `${editTools()}${readings.length?'':dataCallout()}<div class="home-grid ${hasRepresentation()?'':'stats-only'} ${boardDraft?'board-editing':''}">${hasRepresentation()?`<section class="hero-body ${profile?.representation==='digital'?'vitruvian-hero':''}">${personalVisual(onBoard)}${!portraitURL&&profile?.representation==='photo'?'<button class="portrait-cta" data-action="portrait-studio">Illustrative portrait · Create yours ↗</button>':''}<div class="hero-bottom">${insights?`<div class="hero-overline">${insights}</div>`:''}${todayStrip(todayEvents())}</div></section>`:''}<div class="dashboard-data">${hasRepresentation()?'':insights+todayStrip(todayEvents())}<div class="widget-board bento ${boardDraft?'':'packed'}">${trend?`<div class="bento-extra span-3 tall" style="--c:1;--r:1;--w:3;--h:2">${trend}</div><div class="bento-extra tall" style="--c:4;--r:1;--w:1;--h:2">${figureCard()}</div>`:''}${layout.widgets.map((w,i)=>{const at=packed.get(w.id);return `<div class="widget-slot widget-${w.id} size-${w.size} ${w.id===tile&&w.size!=='large'?'is-hero-slot':''}" data-widget-id="${w.id}" ${at&&!boardDraft?`style="--c:${at.c};--r:${at.r};--w:${at.w};--h:${at.h}"`:''}>${boardDraft?widgetControls(w,i,layout.widgets.length):''}<div class="widget-content" ${boardDraft?'inert':''}>${dashboardWidget(w.id,w.id===tile)}</div></div>`}).join('')}${!layout.widgets.length?`<div class="empty-board panel"><h2>A little room for what matters.</h2><p>Add widgets to create your dashboard.</p><button class="btn light" data-action="${boardDraft?'add-widgets':'edit-dashboard'}">${icon('plus')} Add widgets</button></div>`:''}</div></div></div>`}

function nutrition(){const t=totals(mealData),den=t.protein*4+t.carbs*4+t.fat*9,p=den?t.protein*4/den*100:0,c=den?(t.protein+t.carbs)*4/den*100:0;return `<div class="nutrition-workspace"><div class="nutrition-canvas"><section class="panel nutrition-assistant" aria-label="Nutrition conversation"><div id="nutrition-chat-host"></div></section><aside class="nutrition-day"><section class="panel daily-balance"><div class="panel-head"><h3>Daily balance</h3><span class="tag">${mealData.length} ${mealData.length===1?'entry':'entries'}</span></div><div class="balance-summary"><div class="donut ${den?'':'is-empty'}" style="--p:${p}%;--c:${c}%"><span>${Math.round(t.calories)}<small>kcal logged</small></span></div><div class="macro-lines">${[['protein','Protein',p],['carbs','Carbs',c-p],['fat','Fat',den?100-c:0]].map(([k,n,share])=>`<div class="macro-line ${k}"><i></i><span>${n}</span><strong>${Math.round(t[k])}<small> g</small></strong><em>${Math.round(share)}%</em></div>`).join('')}</div></div><p class="mini-note">Estimated from your logged meals.</p></section><section class="panel meal-journal"><div class="panel-head"><h3>Food journal</h3><span class="journal-date">${new Date(nutritionDay+'T12:00:00').toLocaleDateString(dateLocale,{month:'short',day:'numeric'})}</span></div><div class="journal-scroll" tabindex="0" aria-label="Meals for the selected day">${mealData.length?mealData.map(m=>`<div class="meal"><span class="meal-icon">${icon('food')}</span><div class="meal-copy"><h3>${esc(m.name)}</h3><p>${esc(m.meal_type)} · ${Math.round(m.protein)} g protein</p></div><div class="kcal">${Math.round(m.calories)}<small>kcal</small></div><button class="icon-btn delete-button" data-delete-meal="${m.id}" aria-label="Delete ${esc(m.name)}">${icon('trash')}</button></div>`).join(''):`<div class="empty">${icon('food')}<h3>Your day starts with a bite.</h3><p>Your meals for this day will appear here.</p>${capabilities.mealAnalysis?button('Describe a meal','meal'):button('Add a meal','meal-manual')}</div>`}</div></section></aside></div></div>`}

function bodyCards(){return metrics.filter(m=>m.group==='body').map(m=>{const r=reading(m.kind);return `<article class="metric body-measurement ${m.color}"><div class="metric-top">${m.name}</div><button class="body-entry-value" data-body-entry="${m.kind}" aria-label="Add ${m.name.toLowerCase()} measurement"><span class="metric-number">${r?formatValue(r.value,m.kind):'—'}<small>${m.unit}</small></span><span class="metric-source">${r?esc(r.source)+' · '+new Date(r.observed_at).toLocaleDateString(dateLocale,{timeZone:'UTC',month:'short',day:'numeric'}):'Your measurement, when you’re ready'}</span></button><div class="body-card-actions"><button class="btn light" data-body-entry="${m.kind}">${icon('plus')} Add entry</button>${r?`<button class="text-button" data-metric="${m.kind}">Trend ↗</button>`:''}</div></article>`}).join('')}
function body(){return `<div class="body-page ${hasRepresentation()?'':'stats-only'}">${hasRepresentation()?`<section class="panel body-visual">${personalVisual()}<p class="mini-note">${profile.representation==='digital'?digitalFigure(profile.gender).label+' · Illustrative artwork':portraitURL?'Your AI portrait':'Illustrative portrait'} · Not a body composition scan</p>${profile.representation==='photo'?'<button class="text-button" data-action="portrait-studio">Personalise my portrait ↗</button>':'<button class="text-button" data-action="profile-settings">Change my representation ↗</button>'}</section>`:''}<section class="body-measurements"><div class="body-card-grid">${bodyCards()}</div><section class="panel body-source-note"><span class="eyebrow">A PICTURE OF YOUR PROGRESS</span><h3>Make your measurements part of the story.</h3><p>Add your weight, body fat or lean mass directly from a scale, a scan or your records. Each entry keeps its date so you can follow changes over time.</p><p class="mini-note">No wearable connection needed. Your portrait is a visual representation, not a measurement.</p></section></section></div>`}
function bodyEntry(kind){openBodyMeasurement({kind,readings,save:data.saveBodyMeasurement,remove:data.removeBodyMeasurement,onChanged:async()=>{try{await refresh();await render();toast('Measurements updated')}catch{toast('Saved. Refresh to see the latest numbers.')}},showModal,heading,closeModal,openTrend:metricDetail})}
const dayLabel=day=>esc(new Date(day+'T12:00:00').toLocaleDateString(dateLocale,{year:'numeric',month:'short',day:'numeric'}));
// Results are grouped by test and unit (values in different units are never compared), newest first.
function labGroups(){const groups=new Map();for(const r of [...labResults].sort((a,b)=>b.collected_on.localeCompare(a.collected_on))){const key=r.marker.toLowerCase()+'|'+r.unit;if(!groups.has(key))groups.set(key,[]);groups.get(key).push(r)}return [...groups.values()].map(rows=>[rows[0],rows[1],rows.length])}
// Where the value sits against the laboratory's range: the band is the reference, the dot the result.
function rangeBar(r){const low=r.reference_low,high=r.reference_high,text=`${low??'—'} – ${high??'—'}`;if(low==null||high==null||high<=low)return `<span class="range-text">${text}</span>`;const pad=(high-low)/2,pos=Math.max(0,Math.min(100,(Number(r.value)-(low-pad))/(2*(high-low))*100)),status=labRangeStatus(r);return `<span class="range-bar ${status==='Within reference'?'':'out'}" role="img" aria-label="${esc(r.value)} against a reference of ${text}"><i class="range-band"></i><b style="left:${pos.toFixed(1)}%"></b></span><span class="range-text">${text}</span>`}
// History over time: shaded reference band, results outside it marked.
function labChart(history,r){if(history.length<2)return seriesChart(history.map(x=>({value:x.value,observed_at:x.collected_on+'T12:00:00Z'})));const values=history.map(x=>Number(x.value)).concat([r.reference_low,r.reference_high].filter(v=>v!=null).map(Number)),min=Math.min(...values),max=Math.max(...values),span=max-min||1,y=v=>(170-(v-min)/span*140).toFixed(1),start=Date.parse(history[0].collected_on),dur=Date.parse(history.at(-1).collected_on)-start||1,x=d=>(30+(Date.parse(d)-start)/dur*540).toFixed(1);const band=r.reference_low!=null&&r.reference_high!=null?`<rect class="lab-band" x="0" width="600" y="${y(r.reference_high)}" height="${(y(r.reference_low)-y(r.reference_high)).toFixed(1)}"/>`:'';return `<svg class="lab-chart" viewBox="0 0 600 200" preserveAspectRatio="none" role="img" aria-label="${history.length} results over time">${band}<polyline points="${history.map(h=>`${x(h.collected_on)},${y(h.value)}`).join(' ')}"/>${history.map(h=>`<circle class="${['Above reference','Below reference'].includes(labRangeStatus(h))?'out':''}" cx="${x(h.collected_on)}" cy="${y(h.value)}" r="5"><title>${esc(h.collected_on)}: ${esc(h.value)} ${esc(h.unit)} · ${labRangeStatus(h)}</title></circle>`).join('')}</svg>`}
function labChange(r,previous){if(!previous)return '<span class="lab-change">First result</span>';const diff=Number(r.value)-Number(previous.value);return `<span class="lab-change ${diff?'':'same'}">${diff>0?'↑':diff<0?'↓':'='} ${Math.abs(diff).toLocaleString(dateLocale,{maximumFractionDigits:2})}<small>since ${dayLabel(previous.collected_on)}</small></span>`}
function reports(){const labFiles=records.filter(r=>r.kind==='lab'),groups=labGroups();return `<section class="panel"><div class="panel-head"><h3>Blood results</h3><span class="tag">${groups.length} ${groups.length===1?'test':'tests'} · ${labResults.length} ${labResults.length===1?'result':'results'}</span></div>${labResults.length?`<div class="lab-table-wrap"><table class="lab-table"><thead><tr><th>Test / latest</th><th>Result</th><th>Change</th><th>Lab reference</th><th>Status</th><th></th></tr></thead><tbody>${groups.map(([r,previous,count])=>`<tr><td><button class="text-button lab-name" data-lab="${r.id}">${esc(r.marker)}</button><small>${dayLabel(r.collected_on)}${r.laboratory?' · '+esc(r.laboratory):''}${count>1?` · ${count} results`:''}</small></td><td><strong>${esc(r.value)}</strong> <small>${esc(r.unit)}</small></td><td>${labChange(r,previous)}</td><td>${rangeBar(r)}</td><td><span class="tag ${['Above reference','Below reference'].includes(labRangeStatus(r))?'warm':''}">${labRangeStatus(r)}</span></td><td><button class="icon-btn" data-lab="${r.id}" aria-label="View ${esc(r.marker)} history">${icon('arrow')}</button></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty">${icon('vitals')}<h3>Your results, over time</h3><p>Add the value, unit and reference range exactly as printed by your laboratory.</p>${button('Add a blood result','lab')}</div>`}</section><section class="panel" style="margin-top:24px"><div class="panel-head"><h3>Lab documents</h3><span class="tag">${labFiles.length} files</span></div>${labFiles.length?labFiles.map(r=>`<div class="record">${icon(r.kind==='photo'?'camera':'report')}<div><h3>${esc(r.name)}</h3><p>${r.kind==='photo'?'Reference photo':'Lab report'} · ${new Date(r.created_at).toLocaleDateString(dateLocale)}</p></div><div class="actions"><button class="icon-btn" data-download="${r.id}" aria-label="Open ${esc(r.name)}">${icon('arrow')}</button><button class="icon-btn delete-button" data-delete-record="${r.id}" aria-label="Delete ${esc(r.name)}">${icon('trash')}</button></div></div>`).join(''):`<div class="empty">${icon('report')}<h3>A home for your health history</h3><p>Upload a PDF or image. Only your account can access it.</p>${button('Upload a report','upload')}</div>`}</section><p class="mini-note">Reference flags compare your entry with the range you provide. They are not a diagnosis. Values with different units are kept separate.</p>`}
function labForm(row={}){showModal(`${heading(row.id?'Edit blood result':'Add a blood result','Health records')}<p>Copy the numeric value and unit exactly from your laboratory report.</p><form id="lab-form" style="margin-top:22px"><div class="form-grid"><label class="field">Test name<input name="marker" required maxlength="120" placeholder="e.g. Ferritin" value="${esc(row.marker||'')}"></label><label class="field">Collection date<input name="collected_on" type="date" required max="${localDay()}" value="${row.collected_on||localDay()}"></label><label class="field">Result<input name="value" type="number" required min="-1000000000" max="1000000000" step="any" value="${row.value??''}"></label><label class="field">Unit<input name="unit" required maxlength="40" placeholder="e.g. ng/mL" value="${esc(row.unit||'')}"></label><label class="field">Lower reference limit (optional)<input name="reference_low" type="number" step="any" value="${row.reference_low??''}"></label><label class="field">Upper reference limit (optional)<input name="reference_high" type="number" step="any" value="${row.reference_high??''}"></label></div><label class="field">Laboratory (optional)<input name="laboratory" maxlength="160" value="${esc(row.laboratory||'')}"></label><label class="field">Notes (optional)<textarea name="notes" maxlength="2000">${esc(row.notes||'')}</textarea></label><div id="form-error"></div><div class="dialog-footer"><p>Saved privately to your account.</p><button class="btn" type="submit">Save result</button></div></form>`);$('#lab-form').onsubmit=e=>{e.preventDefault();busy(e.target,async()=>{await data.saveLabResult(Object.fromEntries(new FormData(e.target)),row.id);await refresh();closeModal();page='Blood records';await render();toast('Blood result saved')})}}
function labDetail(id){const r=labResults.find(r=>r.id===id);if(!r)return;const history=labResults.filter(x=>x.marker.toLowerCase()===r.marker.toLowerCase()&&x.unit===r.unit).sort((a,b)=>a.collected_on.localeCompare(b.collected_on));showModal(`${heading(esc(r.marker),'Blood results / '+esc(r.laboratory||'Your report'))}<p>${esc(r.collected_on)} · Entered from your laboratory report</p><div class="figure-number">${esc(r.value)}<small> ${esc(r.unit)}</small></div><span class="tag">${labRangeStatus(r)}</span><p style="margin-top:18px">Laboratory reference: ${r.reference_low??'—'} – ${r.reference_high??'—'} ${esc(r.unit)}</p><div class="trend-chart">${labChart(history,r)}</div><div class="axis"><span>${history[0]?.collected_on||''}</span><span>${history.at(-1)?.collected_on||''}</span></div><p class="mini-note">${history.length} result(s) in ${esc(r.unit)}. Reference ranges may change between laboratories.</p>${r.notes?`<p>${esc(r.notes)}</p>`:''}<div class="dialog-footer"><button class="btn light" id="edit-lab">Edit result</button><button class="text-button" id="delete-lab">Delete result</button></div>`);$('#edit-lab').onclick=()=>labForm(r);$('#delete-lab').onclick=()=>{showModal(`${heading('Delete this blood result?')}<p>This permanently removes ${esc(r.marker)} collected on ${esc(r.collected_on)}.</p><div class="dialog-footer">${button('Keep result','close','light')}<button class="btn" id="confirm-lab-delete">Delete result</button></div>`);$('#confirm-lab-delete').onclick=async()=>{try{$('#confirm-lab-delete').disabled=true;await data.removeLabResult(id);await refresh();closeModal();await render();toast('Result deleted')}catch(e){err(e)}}}}
function importWearable(provider){openWearableImport(provider,{showModal,heading,icon,api:data.api,done:async count=>{closeModal();await refresh();await render();toast(count+' measurements imported')}})}

function integrations(){const whoop=connections.find(c=>c.provider==='whoop');return `<div class="integrations"><section class="integration"><div class="integration-logo">W</div><h2>WHOOP</h2><span class="tag ${whoop?'':'warm'}">${whoop?'Connected':capabilities.whoop?'Ready to connect':'Activation pending'}</span><p>Recovery, sleep, resting heart rate, HRV, blood oxygen and respiratory rate. Includes skin temperature, sleep stages, efficiency and consistency. Imports up to 90 days.</p>${whoop?`<p class="mini-note">${whoop.last_synced_at?'Last synced '+new Date(whoop.last_synced_at).toLocaleString(dateLocale,{dateStyle:'medium',timeStyle:'short'}):'First synchronization pending'}</p>`:''}${whoop?`<div class="integration-actions">${button('Sync now','sync-whoop','light')+button('Disconnect','disconnect-whoop','light')}</div>`:capabilities.whoop?button('Connect WHOOP','whoop','light'):'<p class="mini-note">WHOOP authorization is being configured. Connecting will become available here when activated.</p>'}</section><section class="integration"><div class="integration-logo">G</div><h2>Fitbit / Google Health</h2><span class="tag">${readings.some(r=>r.source.startsWith('Fitbit import'))?'Data imported':'File import available'}</span><p>Import recorded heart rate, sleep, HRV, weight and body-fat measurements from your data export.</p>${button('Import Fitbit data','import-fitbit','light')}<small class="integration-mode">Automatic sync needs an approved Google Health app.</small></section><section class="integration"><div class="integration-logo">⌘</div><h2>Apple Watch / Health</h2><span class="tag">${readings.some(r=>r.source.startsWith('Apple Health import'))?'Data imported':'File import available'}</span><p>Import Apple Watch sleep stages, heart rate, HRV, blood oxygen, breathing, wrist temperature, steps and activity-ring energy, plus scale measurements, from your iPhone Health export. Exports of any size work.</p>${button('Import Apple Health','import-apple','light')}<small class="integration-mode">Automatic sync needs an iPhone companion app.</small></section></div>${connectionError?`<p class="error">Could not check connection status: ${esc(connectionError)} ${button('Try again','refresh','light')}</p>`:''}<section class="panel" style="margin-top:24px"><h3>Measured. Always clear.</h3><p style="margin-top:10px">Every reading keeps its source and date. Disconnecting stops access; previously imported measurements stay in your records. Nutrition logs do not measure glucose, inflammation or water retention.</p></section>`}
function settings(){return `<section class="panel"><h2>Profile</h2><div class="settings-row"><div><h3>Profile & view</h3><p>${profile?esc(({photo:"Personal portrait",digital:digitalFigure(profile?.gender).label,stats:"Statistics only"})[profile.representation])+" · "+profile.age+" years":"Personalize your workspace"}</p><p class="mini-note">Peer comparisons ${profile?.peer_opt_in?"enabled":"off"}. Change your image, age or participation anytime.</p></div>${button("Edit preferences","profile-settings","light")}${profile?.representation==='photo'?button("Portrait studio","portrait-studio","light"):''}</div><div class="settings-row"><div><h3>AI</h3><p>${capabilities.chatAI?esc(providerName(capabilities.chatAI.provider))+' · '+esc(capabilities.chatAI.model)+'. Powers chat, meal analysis and journal reflections.':'Connect ChatGPT, Claude, Gemini, Grok, Mistral, DeepSeek, Groq or OpenRouter with your own API key.'}</p><p class="mini-note">Portraits and voice notes: ${capabilities.personalAI||capabilities.chatAI?.provider==='openai'?'OpenAI connected':'optional OpenAI key not added'}.</p></div><button class="btn light" data-action="chat-connect">${capabilities.chatAI?'Manage AI':'Connect your AI'}</button></div><div class="settings-row"><div><h3>Account</h3><p>${esc(data.user.email)}</p></div><span class="tag">Signed in</span></div><div class="settings-row"><div><h3>Connected sources</h3><p>Manage what comes into your health profile.</p></div><button class="btn light" data-nav="Integrations">Manage sources</button></div><div class="settings-row"><div><h3>Export your data</h3><p>Download your complete meal history, readings, lab results and file metadata. CSV opens in any spreadsheet.</p></div><div class="actions">${button('CSV','export-csv','light')}${button('JSON','export','light')}</div></div><div class="settings-row"><div><h3>Privacy & data use</h3><p>Understand how files, food descriptions and recordings are handled.</p></div>${button('Read details','privacy','light')}</div><div class="settings-row"><div><h3>Sign out</h3><p>End your session on this device.</p></div>${button('Sign out','logout','light')}</div></section><details class="panel profile-section"><summary>${icon('peers')} Age-group comparison <span>Private to you</span></summary><div id="profile-peers">${peerPage(peerResult)}</div></details><details class="panel profile-section"><summary>${icon('camera')} Portrait photos <span>${records.filter(r=>r.kind==='photo').length} files</span></summary><p class="mini-note">Private reference photos for your portrait. These are separate from blood records.</p>${records.filter(r=>r.kind==='photo').map(r=>`<div class="record">${icon('camera')}<div><h3>${esc(r.name)}</h3><p>Reference photo · ${new Date(r.created_at).toLocaleDateString(dateLocale)}</p></div><div class="actions"><button class="icon-btn" data-download="${r.id}" aria-label="Open ${esc(r.name)}">${icon('arrow')}</button><button class="icon-btn delete-button" data-delete-record="${r.id}" aria-label="Delete ${esc(r.name)}">${icon('trash')}</button></div></div>`).join('')||'<p class="mini-note">Your reference photos will appear here.</p>'}</details>`}
async function refresh(){const owner=data.user?.id;if(!owner)return;const next=await Promise.all([data.meals(nutritionDay),data.readings(),data.records(),data.labResults(),data.profile()]);if(data.user?.id!==owner)return;[mealData,readings,records,labResults,profile]=next;if(readings.length)setDemo(false);demo=!readings.length&&demoWanted();if(demo)readings=demoReadings();portraitURL=await data.profilePhoto(profile);portraitChecked=Date.now();try{journalData=await data.journalEntries();journalError=''}catch(e){journalError=e.message}peerResult=null;connections=[];connectionError='';try{const status=await data.api('connections');if(data.user?.id!==owner)return;connections=status.connections||[];capabilities=status.capabilities||{}}catch(e){connectionError=e.message}}

// One header per page: its title, a line of page-specific context and the page's own actions.
function pageLead(){const signals=metrics.filter(m=>m.group!=='sleep'&&m.group!=='body'&&reading(m.kind)).length,night=reading('sleep');return ({Vitals:signals?`A closer look at your signals · ${signals} ${signals===1?'measurement':'measurements'} from your connected sources.`:'Connect a source to see your signals.',Sleep:night?'Your last recorded night · '+new Date(night.observed_at).toLocaleDateString(dateLocale,{weekday:'long',month:'long',day:'numeric'}):'Connect a wearable to see your sleep.',Body:'Measurements you add. Progress you can see.',Nutrition:'A conversation about what nourishes you.',Journal:'Private check-ins that connect your day to your data.','Blood records':'Blood results and original reports, saved to your private account.',Integrations:'Your account. Your measurements. Your choice.',Profile:'Your preferences, AI connections and data.'})[page]||''}
function pageActions(){if(page==='Vitals'||page==='Sleep')return `<button class="btn light" data-nav="Integrations">Manage sources ${icon('arrow')}</button>`;if(page==='Body')return `<button class="btn light" data-action="profile-settings">Change representation ${icon('arrow')}</button>`;if(page==='Blood records')return button(icon('plus')+'<span>Add blood result</span>','lab')+button(icon('upload')+'<span>Upload report</span>','upload','light');if(page==='Nutrition')return `<label class="nutrition-day-control"><span>Viewing</span><input aria-label="Nutrition day" id="nutrition-day" type="date" max="${localDay()}" value="${nutritionDay}"></label>`+button(icon('plus')+'<span>Add manually</span>','meal-manual','light');return ''}
function accountMenu(name,compact=false){return `<details class="account-menu ${compact?'compact':'sidebar-account'}"><summary aria-label="${compact?'Account menu':'Profile menu'}"><span class="avatar-letter">${esc(name.slice(0,1).toUpperCase())}</span>${compact?'':`<span class="account-name">${esc(name)}<small>Your profile</small></span><span class="account-chevron">⌃</span>`}</summary><div class="account-popover"><span class="eyebrow">YOUR WORKSPACE</span><button data-nav="Profile">${icon('body')} Profile</button><button data-nav="Integrations">${icon('link')} Integrations</button><button data-action="privacy">${icon('shield')} Privacy & data</button><button class="account-signout" data-action="logout">${icon('logout')} Sign out</button></div></details>`}
function chatDock(){return `<div id="chat-dock" class="chat-dock ${chatOpen?'is-open':''}">${chatOpen?'<div class="chat-scrim" data-action="close-chat" aria-hidden="true"></div>':''}<section class="chat-window" aria-label="Xeyo chatbot" ${chatOpen?'':'hidden'}><div class="chat-window-bar"><span>${orb()} Ask Xeyo</span><button class="icon-btn" data-action="close-chat" aria-label="Close chatbot">${icon('close')}</button></div><div id="chatbot-host"></div></section><button class="chat-launcher" data-action="toggle-chat" aria-expanded="${chatOpen}" aria-label="${chatOpen?'Close chatbot':'Open chatbot'}">${orb()}<span>Ask Xeyo<small>A little more clarity</small></span>${icon('chat')}</button></div>`}
async function toggleChat(force){chatOpen=force??!chatOpen;const dock=$('#chat-dock');if(!dock)return;dock.outerHTML=chatDock();wire($('#chat-dock'));if(chatOpen){await chatbot.mount();$('#chat-message')?.focus()}else document.querySelector('.chat-launcher')?.focus();}
async function render(){const previousChat=$('#chat-dock');if(profile?.representation==='photo'&&Date.now()-portraitChecked>55*60000){portraitURL=await data.profilePhoto(profile);portraitChecked=Date.now();}const name=data.user?.user_metadata?.name||data.user?.email?.split('@')[0]||'there';app.innerHTML=`<aside class="sidebar"><button class="brand" data-nav="Home" aria-label="Xeyo — home">${orb()}<span class="brand-name">Xeyo</span></button><nav class="nav">${navs.map(([n,i])=>`<button class="${page===n?'active':''}" data-nav="${n}" aria-label="${n}" ${page===n?'aria-current="page"':''}>${icon(i)}<span>${n}</span></button>`).join('')}</nav><div class="sidebar-bottom">${accountMenu(name)}</div></aside><main class="shell ${page==='Home'&&!boardDraft&&!demo&&readings.length&&hasRepresentation()&&boardRows(currentBoard(),{hero:heroKind(currentBoard())})<=4?'home-fitted':''} ${hasRepresentation()?'':'theme-stats'}" data-page="${page}">${demoBanner()}<header class="header"><div>${page==='Home'?`<div class="hello">Hello,</div><h1>${esc(name)}.</h1><p>Here’s your health today.</p>`:`<h1>${page}</h1><p>${pageLead()}</p>`}</div>${page!=='Home'&&pageActions()?`<div class="page-actions">${pageActions()}</div>`:''}<div class="header-actions">${page==='Home'?`<span>${new Date().toLocaleDateString(dateLocale,{weekday:'short',month:'short',day:'numeric'})}</span>`:''}<div id="sync-control">${syncControl()}</div>${page==='Home'?`<button class="btn light edit-dashboard" data-action="edit-dashboard" aria-label="Edit dashboard">${icon('settings')}<span>Edit widgets</span></button>`:''}</div></header><div id="page">${page==='Home'?home():page==='Nutrition'?nutrition():page==='Body'?body():page==='Blood records'?reports():page==='Integrations'?integrations():page==='Profile'?settings():page==='Journal'?'<div id="journal-host"></div>':`${page==='Sleep'?sleepPage():vitalsPage()}`}</div><footer class="footer"><span>A little more clarity, every day.</span><span>Personal health records · Not a diagnosis</span></footer>${chatDock()}</main>`;if(previousChat&&chatOpen)$('#chat-dock').replaceWith(previousChat);wire();bindBoard();bindDepth();if(page==='Nutrition')mealLogger.refresh();if(page==='Profile')loadPeers();if(chatOpen&&!previousChat)chatbot.mount();if(page==='Journal')journal.mount();syncRoute()}
addEventListener('popstate',()=>{if(authMode!=='account'||!data.user)return;const next=pageFromHash();if(next===page)return;closeModal();if(page==='Nutrition')mealLogger.cancel();boardDraft=null;if(next!=='Home')chatOpen=false;page=next;render().then(()=>window.scrollTo(0,0)).catch(err)});
function showModal(html,wide=false){if(!$('#modal').contains(document.activeElement))lastFocus=document.activeElement;$('#modal').innerHTML=`<section class="dialog ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><button class="icon-btn close" data-action="close" aria-label="Close">${icon('close')}</button>${html}</section>`;$('#modal').hidden=false;document.body.style.overflow='hidden';wire($('#modal'));$('.close').focus()}
function cancelRecording(){mealLogger.cancel()}
// Escape runs this on every page, so it must not touch the inline meal composer when no dialog is open.
function closeModal(){if($('#modal').hidden)return;if(page!=='Nutrition')cancelRecording();cancelImport();$('#modal').hidden=true;$('#modal').innerHTML='';document.body.style.overflow='';lastFocus?.focus()}
function heading(t,s='Your health, in perspective'){return `<div class="eyebrow">${s}</div><h2 id="dialog-title">${t}</h2>`}
function aiSettings(afterSave){
 showModal(`${heading('OpenAI for portraits and voice','Settings / AI')}<p>Connect your own OpenAI API key for your personal portrait and voice notes. It is also used for meal logging. Prefer Claude, Gemini or another AI for chat and meals? Use Your AI in Profile.</p><div class="ai-key-info"><span class="tag ${capabilities.personalAI?'':'warm'}">${capabilities.personalAI?'Connected':'Not connected'}</span><p>Your key is encrypted on our server and used only for your requests. API usage is billed to your OpenAI account.</p></div><form id="ai-key-form"><label class="field">${capabilities.personalAI?'Replace OpenAI API key':'OpenAI API key'}<input name="key" type="password" required autocomplete="off" spellcheck="false" placeholder="sk-…" minlength="20" maxlength="384"></label><p class="mini-note">Create a key in <a href="https://platform.openai.com/api-keys" target="_blank" rel="noopener">your OpenAI account ↗</a>. The project needs API billing and access to the nutrition, transcription and gpt-image-2 image models. A ChatGPT subscription alone is not an API connection.</p><div id="form-error"></div><div class="dialog-footer"><span class="meal-private">${icon('shield')} Stored encrypted</span><button class="btn" type="submit">${capabilities.personalAI?'Replace key':'Connect key'} ${icon('arrow')}</button></div></form>${capabilities.personalAI?'<button class="text-button remove-ai-key" id="remove-ai-key">Remove my key from this app</button>':''}`);
 $('#ai-key-form').onsubmit=e=>{e.preventDefault();busy(e.target,async()=>{const input=e.target.elements.key;let key=input.value.trim();try{await data.api('ai-key-save',{key})}finally{input.value='';key=''}await refresh();closeModal();await render();toast('Your OpenAI key is connected');afterSave?.()})};
 if($('#remove-ai-key'))$('#remove-ai-key').onclick=()=>{showModal(`${heading('Remove your API connection?')}<p>This deletes the stored key from this app. Your saved meals stay in your journal. To revoke the key everywhere, also remove it in your OpenAI account.</p><div id="form-error"></div><form id="remove-ai-form"><div class="dialog-footer">${button('Keep connection','close','light')}<button class="btn" type="submit">Remove key</button></div></form>`);$('#remove-ai-form').onsubmit=e=>{e.preventDefault();busy(e.target,async()=>{await data.api('ai-key-remove');await refresh();closeModal();await render();toast('API key removed')})}};
}
const journal=createJournal({getReadings:()=>readings,getCapabilities:()=>capabilities,load:data.journalEntries,save:data.saveJournal,remove:data.deleteJournal,removeReflection:data.deleteReflection,api:data.api,orb,showModal,heading,closeModal,onChanged:async entries=>{journalData=entries;journalError=''},bindNav:root=>wire(root)});
const chatbot=createChatbot({api:data.api,loadMessages:data.chatMessages,orb,showModal,heading,closeModal,getCapabilities:()=>capabilities,manageOpenAI:()=>aiSettings(),bindNav:()=>wire($('#chatbot-host')),onConnected:async()=>{await refresh();await render();toast('Your AI is connected')}});
const mealLogger=createMealLogger({showModal,getHost:()=>page==='Nutrition'?$('#nutrition-chat-host'):null,heading,icon,api:data.api,getDay:()=>nutritionDay,getCapabilities:()=>capabilities,connectAI:()=>chatbot.connect(),manual:()=>mealForm(),save:async rows=>{const saved=await data.saveMeals(rows);await settle();return saved},remove:async ids=>{await data.removeMeals(ids);await settle()},update:async rows=>{await data.updateMeals(rows);await settle()}});
// The write already succeeded; a failed reload must not be reported as a failed save.
async function settle(){try{await refresh();await render()}catch{toast('Saved. Refresh to see the latest numbers.')}}
async function openMeal(){if(page!=='Nutrition'){page='Nutrition';await render();window.scrollTo(0,0)}$('#meal-description')?.focus()}
function formError(e){let target=$('#form-error');if(target)target.innerHTML=`<div class="error">${esc(e.message)}</div>`;else err(e)}
function busy(form,promise){const b=form.querySelector('[type=submit]');if(b.disabled)return;b.disabled=true;return promise().catch(formError).finally(()=>b.disabled=false)}
function upload(kind='lab'){showModal(`${heading(kind==='lab'?'Add a lab report':'Add a reference photo','Private records')}<p>${kind==='photo'?'Photos are stored privately as references. They are not used to infer body fat or reconstruct your body.':'Your original report will be stored privately. Automatic interpretation is not enabled.'}</p><form id="upload-form"><label class="upload-zone" style="margin-top:20px">${icon('upload')}<span>Choose a ${kind==='photo'?'photo':'PDF or image'}</span><input name="file" type="file" accept="${kind==='photo'?'image/*,.heic,.heif':'application/pdf,image/jpeg,image/png,image/webp'}" required></label><p class="mini-note">Up to 10 MB. Uploaded to your account’s private storage.</p><div id="form-error"></div><div class="dialog-footer"><p>Visible only to your account</p><button class="btn" type="submit">Upload privately</button></div></form>`);$('#upload-form').onsubmit=e=>{e.preventDefault();busy(e.target,async()=>{await data.uploadRecord(new FormData(e.target).get('file'),kind);closeModal();await refresh();page='Blood records';await render();toast('Record uploaded')})}}
function metricDetail(kind,siblings){if(['weight','body_fat','lean_mass'].includes(kind)&&!reading(kind)){bodyEntry(kind);return}siblings??=[...new Set(['#page .widget-board [data-metric]','#page .metric-grid [data-metric]','#page [data-metric]'].flatMap(s=>[...document.querySelectorAll(s)]).map(b=>b.dataset.metric))].map(k=>metrics.find(m=>m.kind===k)).filter(Boolean);openMetricDetail({metric:metrics.find(m=>m.kind===kind),reading:reading(kind),readings,showModal,heading,siblings,open:next=>metricDetail(next,siblings)})}
// Meals can always be logged by hand; an AI connection is optional.
function mealForm(){const hour=new Date().getHours(),type=hour<11?'Breakfast':hour<16?'Lunch':hour<22?'Dinner':'Snack';showModal(`${heading('Add a meal','Nutrition')}<p>Enter what you know. Values from a label or another app work best.</p><form id="manual-meal-form"><label class="field">What you ate<input name="name" required maxlength="200" placeholder="e.g. Greek yogurt with berries"></label><div class="form-grid"><label class="field">Meal<select name="meal_type">${['Breakfast','Lunch','Dinner','Snack'].map(t=>`<option ${t===type?'selected':''}>${t}</option>`).join('')}</select></label><label class="field">Day<input name="logged_on" type="date" required max="${localDay()}" value="${nutritionDay}"></label><label class="field">Calories (kcal)<input name="calories" type="number" required min="0" max="10000" step="1" inputmode="numeric"></label><label class="field">Protein (g)<input name="protein" type="number" required min="0" max="10000" step="0.1" value="0"></label><label class="field">Carbs (g)<input name="carbs" type="number" required min="0" max="10000" step="0.1" value="0"></label><label class="field">Fat (g)<input name="fat" type="number" required min="0" max="10000" step="0.1" value="0"></label></div><div id="form-error"></div><div class="dialog-footer"><span>Saved to your food journal.</span><button class="btn" type="submit">Add meal</button></div></form>`);$('#manual-meal-form').onsubmit=e=>{e.preventDefault();busy(e.target,async()=>{const v=Object.fromEntries(new FormData(e.target));await data.saveMeals([{...v,source:'Manual entry'}]);closeModal();nutritionDay=v.logged_on;page='Nutrition';await settle();toast('Meal added')})}}
function weeklySummary(){const rows=weeklyComparison(readings,metrics.filter(m=>m.group!=='body')),since=localDay(new Date(Date.now()-6*86400000)),notes=journalData.filter(e=>e.logged_on>=since);showModal(`${heading('Your week, in summary','Last 7 days compared with the 7 before')}${rows.length?`<div class="lab-table-wrap"><table class="weekly-table"><thead><tr><th>Signal</th><th>Last 7 days</th><th>7 days before</th><th>Change</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.name)}<small>${r.days} ${r.days===1?'day':'days'} recorded</small></td><td><strong>${formatValue(r.week,r.kind)}</strong> <small>${esc(r.unit)}</small></td><td>${formatValue(r.prior,r.kind)} <small>${esc(r.unit)}</small></td><td>${Math.abs(r.pct)<1?'Steady':`${r.pct>0?'↑':'↓'} ${Math.abs(r.pct).toFixed(Math.abs(r.pct)<10?1:0)}%`}</td></tr>`).join('')}</tbody></table></div>`:'<p>A summary appears once you have readings in two consecutive weeks.</p>'}<p class="mini-note">${notes.length} journal ${notes.length===1?'check-in':'check-ins'} this week${demo?' · Sample data':''}. Averages of daily means. A change describes a difference, not whether it is good or bad.</p>`,true)}
function download(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function privacy(){showModal(`${heading('Your data, your choice','Privacy')}<p>Your profile preferences, private chatbot history and signed-in records are stored in the configured Supabase project and protected by account ownership policies. Files use a private bucket and short-lived download links.</p><div class="settings-row"><div><h3>Food descriptions, labels & audio</h3><p>Sent to the AI provider you connected, using your own API key, when you request analysis. Voice notes are transcribed by OpenAI. Meal photos and audio are not saved to your journal; estimated macros are saved to your journal. You can edit values or undo a logged meal.</p></div></div><div class="settings-row"><div><h3>Photos and lab reports</h3><p>Stored privately. Portrait generation sends your selected photo and the style reference to OpenAI when you choose Generate. The result is private and shown only after you approve it. Photos are not used to detect body fat; reports are not automatically diagnosed.</p></div></div><p class="mini-note"><a href="/privacy.html" target="_blank" rel="noopener">Read the full data-use notice ↗</a> · For account deletion: <a href="mailto:tobia@donadon.com">tobia@donadon.com</a></p>`)}
const actions={'toggle-chat':()=>toggleChat(),'close-chat':()=>toggleChat(false),'chat-connect':()=>chatbot.connect(),'portrait-studio':portraitStudio,'add-widgets':widgetGallery,'cancel-board':async()=>{boardDraft=null;await render()},'save-board':async()=>{if(boardSaving)return;boardSaving=true;try{await data.saveDashboardLayout(boardDraft);boardDraft=null;await render();toast('Dashboard saved')}finally{boardSaving=false}},'profile-settings':profileSetup,'retry-peers':loadPeers,'import-apple':()=>importWearable('apple'),'import-fitbit':()=>importWearable('fitbit'),'edit-dashboard':editDashboard,'ai-settings':()=>aiSettings(),lab:()=>labForm(),refresh:()=>refreshConnected(true),digestive:()=>{page='Journal';render()},'digestive-nutrition':()=>{closeModal();page='Nutrition';render()},'digestive-reports':()=>{closeModal();page='Blood records';render()},'sync-whoop':()=>refreshConnected(true),'disconnect-whoop':()=>{showModal(`${heading('Disconnect WHOOP?','Integrations')}<p>Xeyo will stop reading new WHOOP data. Readings already imported stay in your records.</p><div class="dialog-footer">${button('Keep connected','close','light')}<button class="btn" id="confirm-whoop-disconnect">Disconnect</button></div>`);$('#confirm-whoop-disconnect').onclick=async e=>{e.currentTarget.disabled=true;try{await data.api('whoop-disconnect');closeModal();await refresh();await render();toast('WHOOP access revoked. Previously imported readings are retained.')}catch(error){$('#confirm-whoop-disconnect')&&($('#confirm-whoop-disconnect').disabled=false);err(error)}}},close:closeModal,meal:()=>openMeal(),upload:()=>upload(),photo:()=>upload('photo'),privacy,logout:()=>{showModal(`${heading('Sign out of Xeyo?','Account')}<p>You’ll need your email and password to sign back in on this device.</p><div class="dialog-footer">${button('Stay signed in','close','light')}<button class="btn" id="confirm-sign-out">Sign out</button></div>`);$('#confirm-sign-out').onclick=e=>{e.currentTarget.disabled=true;actions['sign-out']().catch(err)}},'sign-out':async()=>{await data.signOut();demo=false;chatOpen=false;boardDraft=null;syncState={busy:false,error:null};chatbot.reset();journal.reset();journalData=[];journalError='';profile=null;portraitURL=null;peerResult=null;emailFlow.clear();history.replaceState({},'',location.pathname);closeModal();showAuth()},whoop:async()=>{const r=await data.api('whoop-connect');if(!r.url?.startsWith('https://api.prod.whoop.com/oauth/oauth2/auth?'))throw Error('Invalid authorization destination.');location.assign(r.url)},google:()=>showModal(`${heading('Fitbit via Google Health','Integration setup')}<p>The legacy Fitbit API retires October 30, 2026. This application needs an approved Google Health API project before live Fitbit synchronization can be enabled.</p><p style="margin-top:20px"><a href="https://developers.google.com/health" target="_blank" rel="noopener">Google Health developer setup ↗</a></p>`),apple:()=>showModal(`${heading('Apple Watch & Apple Health','iPhone companion required')}<p>A website cannot directly read HealthKit. An iPhone companion app must request your permission and securely upload the specific measurements you choose.</p><p style="margin-top:20px">The native companion and background synchronization are not part of this deployed web build. No Apple Health connection is claimed.</p>`),'to-integrations':()=>{closeModal();page='Integrations';render()},export:async()=>download(new Blob([JSON.stringify(await data.exportAll(),null,2)],{type:'application/json'}),`xeyo-export-${localDay()}.json`),'export-csv':async()=>{const all=await data.exportAll(),files={};for(const [name,rows] of Object.entries(all))if(Array.isArray(rows))files[name+'.csv']=strToU8(toCSV(rows));if(all.profile)files['profile.csv']=strToU8(toCSV([all.profile]));download(new Blob([zipSync(files)],{type:'application/zip'}),`xeyo-export-${localDay()}-csv.zip`)},'meal-manual':()=>mealForm(),weekly:()=>weeklySummary(),'edit-goals':()=>editGoals(),'demo-on':async()=>{setDemo(true);await refresh();await render();toast('Exploring sample data. Nothing is saved.')},'demo-off':async()=>{setDemo(false);await refresh();await render();toast('Sample data removed')}};

function wire(root=app){if(!root)return;root.querySelectorAll('[data-body-entry]').forEach(b=>b.onclick=()=>bodyEntry(b.dataset.bodyEntry));const day=root.querySelector('#nutrition-day');if(day)day.onchange=async()=>{if(!day.value)return;mealLogger.cancel();nutritionDay=day.value;try{mealData=await data.meals(nutritionDay);await render()}catch(e){err(e)}};root.querySelectorAll('[data-lab]').forEach(b=>b.onclick=()=>labDetail(b.dataset.lab));root.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>{if(b.dataset.nav==='Chatbot'){closeModal();toggleChat(true).catch(err);return;}chatOpen=false;closeModal();if(page==='Nutrition'&&b.dataset.nav!==page)mealLogger.cancel();if(b.dataset.nav!==page)boardDraft=null;page=b.dataset.nav;if(page==='Home'&&nutritionDay!==localDay()){nutritionDay=localDay();data.meals(nutritionDay).then(rows=>{mealData=rows;render()}).catch(err)}render().then(()=>window.scrollTo(0,0)).catch(err)});root.querySelectorAll('[data-action]').forEach(b=>b.onclick=async()=>{if(b.disabled)return;document.querySelectorAll('.account-menu[open]').forEach(el=>el.open=false);b.disabled=true;try{await actions[b.dataset.action]?.()}catch(e){err(e)}finally{if(b.isConnected)b.disabled=false}});root.querySelectorAll('[data-metric]').forEach(b=>b.onclick=()=>metricDetail(b.dataset.metric));root.querySelectorAll('[data-delete-meal]').forEach(b=>b.onclick=async()=>{const meal=mealData.find(m=>m.id===b.dataset.deleteMeal);if(!meal)return;b.disabled=true;try{await data.removeMeal(meal.id);await settle();toast('Meal removed',{label:'Undo',run:()=>data.saveMeals([meal]).then(settle).then(()=>toast('Meal restored')).catch(err)})}catch(e){if(b.isConnected)b.disabled=false;err(e)}});root.querySelectorAll('[data-download]').forEach(b=>b.onclick=async()=>{try{const url=await data.downloadRecord(b.dataset.download);const a=document.createElement('a');a.href=url;a.target='_blank';a.rel='noopener';a.click()}catch(e){err(e)}});root.querySelectorAll('[data-delete-record]').forEach(b=>b.onclick=()=>{const id=b.dataset.deleteRecord;showModal(`${heading('Delete this record?','Private records')}<p>This removes the stored file and its record. This cannot be undone.</p><div class="dialog-footer">${button('Keep record','close','light')}<button class="btn" id="confirm-delete">Delete record</button></div>`);$('#confirm-delete').onclick=async()=>{try{$('#confirm-delete').disabled=true;await data.deleteRecord(id);closeModal();await refresh();render();toast('Record deleted')}catch(e){err(e)}}})}
let authTimer = null, authBusy = false, enteringAccount = false;
let emailStorage;
try { emailStorage = window.sessionStorage; } catch { emailStorage = null; }
const emailFlow = createEmailFlow(data.db?.auth, emailStorage);

function authNotice(message, success=false) {
  const target=$('#auth-message');
  if(target)target.innerHTML=`<div class="error ${success?'success':''}" role="${success?'status':'alert'}">${esc(message)}</div>`;
}
function renderEmailCooldown() {
  const b=$('#resend-email'), input=$('#verification-email');
  if(!b||!input)return;
  const remaining=emailFlow.waitSeconds(input.value, emailFlow.get()?.type||'signup');
  b.disabled=authBusy||remaining>0||!data.configured;
  b.textContent=authBusy?'Sending…':remaining>0?`Resend in ${remaining>=60?Math.ceil(remaining/60)+' min':remaining+'s'}`:emailFlow.get()?.type==='recovery'?'Resend reset email':'Resend verification email';
  const status=$('#email-wait');
  if(status)status.textContent=remaining>0?'A short pause prevents duplicate emails. Your existing link can still be used.':'Check Spam as well. If you requested several links, use the newest one.';
}
async function enterAccount() {
  if(enteringAccount)return;
  enteringAccount=true;
  try {
  await data.session();
  if(!data.user)throw Error('Sign in to continue.');
  emailFlow.clear();clearInterval(authTimer);authMode='account';
  const hash=new URLSearchParams(location.hash.slice(1)),route=pageFromHash();let connectionResult=new URLSearchParams(location.search).get('connection'),linkError='';
  history.replaceState({},'',location.pathname);
  // WHOOP returns here with its code; only the signed-in account that started the link can finish it.
  if(hash.get('whoop_state')){try{connectionResult=(await data.api('whoop-complete',{state:hash.get('whoop_state'),code:hash.get('whoop_code')})).status}catch(e){connectionResult='failed';linkError=e.message}}
  await refresh();if(!profile){profileSetup();return;}page=connectionResult?'Integrations':route;await render();window.scrollTo(0,0);void refreshConnected();
  if(connectionResult)toast(connectionResult==='connected'?'WHOOP connected and synchronized':connectionResult==='denied'?'WHOOP authorization was cancelled':connectionResult==='connected-needs-sync'?'WHOOP connected. Choose Sync now to import readings.':linkError||'WHOOP connection could not be completed. Try again.');
  } finally { enteringAccount=false; }
}
function showAuth(mode='login') {
  clearInterval(authTimer);authMode=mode;mealLogger.cancel();
  const pending=emailFlow.get(),verify=mode==='verify',recovery=verify&&pending?.type==='recovery';
  const titles={signup:'Make room for you.',forgot:'A fresh start.',reset:'Choose a new password.',verify:recovery?'Check your inbox.':'Confirm your email.',login:'Welcome back.'};
  const description=verify?(recovery?'Open the password-reset link to choose a new password.':'Open the confirmation link in your inbox to activate your private workspace.'):
    mode==='signup'?'Create your private health workspace.':mode==='forgot'?'We’ll send you a secure password-reset link.':mode==='reset'?'Use a unique password with at least 12 characters.':'A clearer picture of your health starts here.';
  const verification=`<div class="verification-symbol">${icon('shield')}</div><div class="verification-steps"><span class="${pending?.delivery==='requested'?'done':''}">1 · Email requested</span><span class="current">2 · Confirm email</span><span>3 · Sign in</span></div><form id="verification-form"><label class="field">Email address<input id="verification-email" name="email" type="email" autocomplete="email" required value="${esc(pending?.email||'')}" placeholder="you@example.com"></label><div id="auth-message" aria-live="polite"></div><button class="btn light" id="resend-email" type="submit">Resend verification email</button><p class="mini-note" id="email-wait"></p></form><button class="btn verified-login" id="verified-login">${recovery?'Back to sign in':'I’ve confirmed my email · Sign in'} ${icon('arrow')}</button><div class="auth-options"><button class="text-button" id="change-email">Use a different email</button></div>`;
  const form=`<form id="auth-form">${mode==='signup'?'<label class="field">Your name<input name="name" autocomplete="given-name" required maxlength="60" placeholder="First name"></label>':''}${mode!=='reset'?`<label class="field">Email address<input type="email" name="email" autocomplete="email" required value="${mode==='login'?esc(pending?.email||''):''}" placeholder="you@example.com"></label>`:''}${mode!=='forgot'?`<label class="field">Password<input type="password" name="password" autocomplete="${mode==='login'?'current-password':'new-password'}" minlength="${mode==='login'?1:12}" maxlength="128" required placeholder="${mode==='login'?'Your password':'At least 12 characters'}"></label>`:''}${['signup','reset'].includes(mode)?'<label class="field">Confirm password<input type="password" name="confirm" autocomplete="new-password" minlength="12" required placeholder="Enter your password again"></label>':''}${mode==='signup'?'<label class="privacy-check"><input name="consent" type="checkbox" required><span>I understand this stores personal health information. <button type="button" class="text-button" data-action="privacy">Read data-use details</button></span></label>':''}<div id="auth-message" aria-live="polite"></div><button class="btn" type="submit" ${!data.configured?'disabled':''}>${mode==='signup'?'Create account':mode==='forgot'?'Send reset link':mode==='reset'?'Update password':'Sign in'} ${icon('arrow')}</button></form><div class="auth-options"><button class="text-button" id="switch-auth">${mode==='login'?'Create an account':'Back to sign in'}</button>${mode==='login'?'<button class="text-button" id="forgot">Forgot password?</button>':''}</div>${mode==='login'&&data.emailConfirmation?'<button class="text-button confirmation-help" id="confirm-help">Still waiting for your confirmation email?</button>':''}`;
  app.innerHTML=`<main class="auth-layout"><section class="auth-art"><div class="brand" aria-label="Xeyo">${orb()}<span class="brand-name">Xeyo</span></div>${portrait()}<div class="auth-copy"><h1>A little more clarity.<br>A healthier you.</h1><p>Your daily signals, nutrition and health records, together in Xeyo.</p></div></section><section class="auth-form"><div class="auth-inner"><div class="eyebrow">YOUR HEALTH, IN PERSPECTIVE</div><h1>${titles[mode]||titles.login}</h1><p>${description}</p>${!data.configured?'<div class="config-note">Account services are not connected yet.</div>':data.testMode?'<div class="config-note">Private beta. Verification email is currently enabled for approved test addresses.</div>':''}${verify?verification:form}</div></section></main>`;
  wire();window.scrollTo(0,0);
  if(verify){
    renderEmailCooldown();authTimer=setInterval(renderEmailCooldown,1000);
    $('#verification-email').oninput=renderEmailCooldown;
    $('#verified-login').onclick=()=>showAuth('login');
    $('#change-email').onclick=()=>showAuth(recovery?'forgot':'signup');
    $('#verification-form').onsubmit=async e=>{
      e.preventDefault();if(authBusy)return;
      const email=$('#verification-email').value.trim();
      if(emailFlow.waitSeconds(email,recovery?'recovery':'signup'))return;
      authBusy=true;renderEmailCooldown();
      try{const result=await emailFlow.send({email,type:recovery?'recovery':'signup',origin:location.origin});
        authNotice(result.limited?'Email requests are temporarily limited. Use the link already in your inbox, or wait for the timer.':'If this address has a pending account, a new link has been requested. Check your inbox and Spam.',!result.limited);
      }catch(e){authNotice(authMessage(e))}finally{authBusy=false;renderEmailCooldown()}
    };
    return;
  }
  $('#switch-auth').onclick=()=>showAuth(mode==='login'?(data.emailConfirmation&&emailFlow.get()?.type==='signup'?'verify':'signup'):'login');
  if($('#forgot'))$('#forgot').onclick=()=>showAuth('forgot');
  if($('#confirm-help'))$('#confirm-help').onclick=()=>{if(emailFlow.get()?.type==='recovery')emailFlow.clear();showAuth('verify')};
  $('#auth-form').onsubmit=async e=>{
    e.preventDefault();if(authBusy)return;
    const form=e.target,submit=form.querySelector('[type=submit]'),v=Object.fromEntries(new FormData(form));
    authBusy=true;submit.disabled=true;submit.textContent='Please wait…';
    try{
      if(!data.configured)throw Error('Account services are not configured.');
      if(v.confirm!==undefined&&v.confirm!==v.password)throw Error('Passwords do not match.');
      if(mode==='signup'||mode==='forgot'){
        const result=await emailFlow.send({email:v.email,type:mode==='forgot'?'recovery':'signup',signup:mode==='signup'?{name:v.name,password:v.password}:undefined,origin:location.origin});
        if(result.session){await enterAccount();return;}
        form.reset();showAuth('verify');
        authNotice(result.limited?'A verification request was made recently. Check your inbox before requesting another link.':'Check your inbox and Spam for the secure link. You can close this page and return after confirming.',!result.limited);
        return;
      }
      const result=mode==='reset'?await data.db.auth.updateUser({password:v.password}):await data.db.auth.signInWithPassword({email:v.email.trim(),password:v.password});
      if(result.error)throw result.error;
      form.reset();await enterAccount();
    }catch(error){
      if(error.code==='email_not_confirmed') {emailFlow.remember(v.email);form.reset();showAuth('verify');authNotice('Your email still needs to be confirmed. Use the link in your inbox, or request a new one.');}
      else authNotice(authMessage(error));
    }finally{
      authBusy=false;
      if(submit.isConnected){submit.disabled=!data.configured;submit.textContent=mode==='signup'?'Create account':mode==='forgot'?'Send reset link':mode==='reset'?'Update password':'Sign in';}
      renderEmailCooldown();
    }
  };
}
$('#modal').onclick=e=>{if(e.target===$('#modal'))closeModal()};addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.key==='Tab'&&!$('#modal').hidden){const els=[...$('#modal').querySelectorAll('button,input,textarea,select,a[href],summary,[tabindex]:not([tabindex="-1"])')].filter(x=>!x.disabled&&x.getClientRects().length),first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
// Path addresses (/vitals, /login…) work on hosts that serve the app for every path; anything else gets a branded page.
function notFound(){app.innerHTML=`<main class="not-found"><div class="brand">${orb()}<span class="brand-name">Xeyo</span></div><span class="eyebrow">Page not found</span><h1>This page doesn’t exist.</h1><p>The link may be old or mistyped. Your data is safe.</p><a class="btn" href="/">Back to Home</a></main>`;document.title='Page not found · Xeyo'}
const authPaths={login:'login','sign-in':'login',signin:'login',signup:'signup','sign-up':'signup',register:'signup','forgot-password':'forgot',reset:'forgot'};
async function start(){
  const slug=(location.pathname.replace(/^\/+|\/+$/g,'')||new URLSearchParams(location.search).get('auth')||'').toLowerCase();
  if(slug&&slug!=='index.html'){const target=Object.keys(routes).find(p=>routes[p]===slug);if(target||authPaths[slug]||slug==='onboarding'||slug==='home')history.replaceState(null,'','/'+(target?'#/'+routes[target]:''));else{notFound();return}if(authPaths[slug]&&!(await data.session().catch(()=>null))){showAuth(authPaths[slug]);return}}
  try{
    await data.session();
    const query=new URLSearchParams(location.search),hash=new URLSearchParams(location.hash.slice(1));
    if(query.has('error')||hash.has('error')){history.replaceState({},'',location.pathname);showAuth('verify');authNotice('This email link has expired or has already been used. Try signing in, or request a new link.');return;}
    if(query.get('reset')==='1'){showAuth('reset');if(!data.user)authNotice('Open a valid password-reset link from your email before changing your password.');return;}
    if(data.user){await enterAccount();}
    else showAuth(data.emailConfirmation&&emailFlow.get()?'verify':'login');
  }catch(e){showAuth();authNotice(authMessage(e));}
}
if(data.db)data.db.auth.onAuthStateChange((event,session)=>{
  if(event==='PASSWORD_RECOVERY')setTimeout(()=>showAuth('reset'),0);
  if(event==='SIGNED_OUT')setTimeout(()=>{journal.reset();journalData=[];journalError='';showAuth()},0);
  if(event==='SIGNED_IN'&&session&&!authBusy&&['login','verify'].includes(authMode))setTimeout(()=>enterAccount().catch(e=>authNotice(authMessage(e))),0);
});
installFormErrors();
start();

document.addEventListener('click',e=>document.querySelectorAll('.account-menu[open]').forEach(el=>{if(!el.contains(e.target))el.open=false}));
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#modal').hidden){const open=document.querySelector('.account-menu[open]');if(open){open.open=false;open.querySelector('summary').focus()}else if(chatOpen)toggleChat(false)}});
